            ",",
            ".", // fails IDN.toASCII, but should pass wrapped version
            "a.", // ditto
            "a.b",
            "a..b",
            "a...b",
            ".a",
            "..a",
    };
    for(String s : asciidots) {
        <ASSERTION_HOLE>;
